import fs from 'node:fs';
import vm from 'node:vm';
import assert from 'node:assert/strict';
const src = fs.readFileSync('/private/tmp/bili-tv-compare-sf_ujml9/app/js/app.js', 'utf8');
function body(name) {
  const start = src.indexOf('    function ' + name + '(');
  assert(start >= 0);
  const end = src.indexOf('\n    function ', start + 1);
  return src.slice(start, end < 0 ? src.length : end);
}
const requests = [];
const pagination = {
  state: {screen: 'search', query: 'B', results: [{bvid: 'A1'}], searchPage: 1},
  loadingMore: false, playing: null, optionsOpen: false, pendingNext: null,
  API: {search(term, page, done) {requests.push({term, page}); done([{bvid: 'B2'}]);}},
  paintResults() {}, Date,
};
vm.createContext(pagination);
vm.runInContext(body('maybeLoadMoreSearch'), pagination);
pagination.maybeLoadMoreSearch({getAttribute() {return '0';}});
assert.deepEqual(requests, [{term: 'B', page: 2}]);
assert.deepEqual(pagination.state.results.map(v => v.bvid), ['A1', 'B2']);
const box = {innerHTML: ''};
const empty = {
  state: {screen: 'search', query: 'B', results: [{bvid: 'A1'}]},
  viewToken: 1, stillViewing() {return true;}, el() {return box;},
  API: {search(term, page, done) {done([]);}}, toast() {},
};
vm.createContext(empty);
vm.runInContext(body('runSearch'), empty);
empty.runSearch();
assert.equal(empty.state.results[0].bvid, 'A1');
assert.match(box.innerHTML, /没有结果/);
const result = {
  baseline: 'ab17b30', execution: 'offline Node VM with extracted production functions and stub API',
  pagination: {draftQuery: 'B', existingResultIds: ['A1'], request: requests[0], resultingIds: pagination.state.results.map(v => v.bvid)},
  emptySearch: {query: 'B', displayedEmpty: true, retainedResultIds: empty.state.results.map(v => v.bvid)},
};
fs.writeFileSync('/private/tmp/bili-tv-compare-sf_ujml9/search-state-result.json', JSON.stringify(result, null, 2) + '\n');
console.log(JSON.stringify(result, null, 2));
